+		"bc":  extBC(spec.isCA),
+		"ski": extSKI(ski),
+	}
+	if spec.kuPresent {
+		exts["ku"] = extKU(spec.ku, spec.kuCritical)
+	}
+	if spec.serverEKU {
+		exts["eku"] = extEKUServerAuth()
+	}
+	if spec.ncPresent {
+		exts["nc"] = extNC(spec.ncPermitted, spec.ncExcluded, spec.ncCritical)
+	}
+	if len(spec.dnsNames) > 0 {
+		exts["san"] = extSAN(spec.dnsNames)
+	}
