// Optional empirical browser oracle for the 30-certificate acceptance matrix.
//
// It serves every generated leaf on an ephemeral loopback HTTPS port and uses
// Chromium (Playwright) to navigate to the certificate's own DNS name, mapped
// to 127.0.0.1 via --host-resolver-rules. The acceptance root must be trusted
// first, e.g.:
//
//   certutil -d sql:$HOME/.pki/nssdb -A -t "C,," \
//     -n ica-acceptance-root -i ../corpus/root.pem
//
// Setup:
//   npm install playwright && npx playwright install chromium
//   node probe.mjs

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import https from 'node:https';
import { chromium } from 'playwright';

const here = dirname(fileURLToPath(import.meta.url));
const accDir = join(here, '..');
const report = JSON.parse(readFileSync(join(accDir, 'report.json'), 'utf8'));
const corpus = join(accDir, 'corpus');

function file(p) {
  return readFileSync(join(corpus, p));
}

function serve(row) {
  const nn = String(row.n).padStart(2, '0');
  const leaf = file(`${nn}-${row.id}.leaf.pem`);
  const key = file(`${nn}-${row.id}.leaf.key`);
  const ca = file(`${nn}-${row.id}.ca-chain.pem`);
  return new Promise((resolve) => {
    const server = https.createServer(
      { key, cert: Buffer.concat([leaf, Buffer.from('\n'), ca]) },
      (_req, res) => res.end('ok'),
    );
    server.listen(0, '127.0.0.1', () => resolve(server));
  });
}

const browser = await chromium.launch({
  headless: true,
  // --no-proxy-server bypasses an ambient dev/CI proxy; MAP * pins the
  // certificate's own DNS name to the loopback test server.
  args: [
    '--no-sandbox',
    '--disable-gpu',
    '--no-proxy-server',
    '--host-resolver-rules=MAP * 127.0.0.1',
  ],
});

const observations = [];
for (const row of report.rows) {
  const server = await serve(row);
  const port = server.address().port;
  const context = await browser.newContext({ ignoreHTTPSErrors: false });
  const page = await context.newPage();
  let navigationOk = false;
  let chromiumError = '';
  try {
    await page.goto(`https://${row.dns}:${port}/`, {
      waitUntil: 'domcontentloaded',
      timeout: 8000,
    });
    navigationOk = true;
  } catch (err) {
    chromiumError = (err.message || '').split('\n')[0].trim();
  } finally {
    await context.close();
    await new Promise((r) => server.close(r));
  }
  observations.push({ id: row.id, navigationOk, chromiumError });
  const tag = navigationOk ? 'ACCEPT' : chromiumError.match(/ERR_CERT_[A-Z_]+/)?.[0] || 'ERROR';
  console.log(`${String(row.n).padStart(2)} ${row.id.padEnd(26)} expected=${row.browser_reject_expected ? 'reject' : 'accept'} observed=${tag}`);
}

await browser.close();
writeFileSync(join(here, 'results.json'), JSON.stringify(observations, null, 2));
console.log(`\nwrote ${observations.length} observations to browser/results.json`);

